// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testRegression_property() public {
        vm.deal(address(c), 1 ether);
        vm.prank(c.owner());
        vm.deal(address(c), 1);
        vm.prank(c.owner());
        bool ok;
        try c.sendMoney(address(c), 1) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(c.depositsCount() == 1, "depositsCount should be 1 in reference");
    }
}
